    82	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    83	     * reservation was never paid, so nothing comes back).
    84	     */
    85	    public synchronized Reservation cancel(long reservationId) {
    86	        Reservation reservation = find(reservationId);
    87	        if (reservation.status() != ReservationStatus.PENDING
    88	                && reservation.status() != ReservationStatus.CONFIRMED) {
    89	            throw notAllowed(reservation, "cancel");
    90	        }
